function note(n,cell,body){const id=`${n}:${cell}`;if(noted.has(id))return;noted.add(id);const src=sourcesByCell.get(`${n}!${cell}`);if(src)body+=`\nSource ${src.source_id}: ${src.source_label}. Fiscal year ${src.fiscal_year}, report FY${src.report_year||'unavailable'}, PDF page ${src.pdf_page||'unavailable'}.\nReported ${src.reported_pdf_value||src.source_value} ${src.reported_pdf_unit}. Workbook ${src.workbook_value} ${src.unit}. ${src.conversion}. Status ${src.status}.\n${src.original_pdf}\n${src.source_url}`;wb.notes.add({id,target:{cell:{sheetName:n,sheetId:sheets[n].sheetId,address:cell}},authorId:own,createdAt:'',body:{plainText:body}});}
function v(n,a,x,fmt){authored.push({n,a,x});const r=sheets[n].getRange(a);r.values=[[x]];if(fmt)r.setNumberFormat(fmt);r.format.font.color=typeof x==='number'?blue:ink;}
function f(n,a,x,fmt){if(x.startsWith('=HYPERLINK(')){const m=x.match(/,\"([^\"]*)\"\)$/);x='=IFERROR('+x.slice(1)+',"'+(m?m[1]:'Source reference')+'")';}authored.push({n,a,formula:x});const r=sheets[n].getRange(a);r.formulas=[[x]];if(fmt)r.setNumberFormat(fmt);r.format.font.color=x.includes('!')?green:'#000000';}
function row(n,r,label,arr,fmt=amount,definition=''){
 v(n,`C${r}`,label);
 const values=arr.map(x=>typeof x==='string'&&x.startsWith('=')?null:x);
 const formulas=arr.map(x=>typeof x==='string'&&x.startsWith('=')?x:null);
 const range=sheets[n].getRange(`E${r}:${col(4+arr.length)}${r}`);
 range.values=[values];
 for(let i=0;i<arr.length;i++){
  const a=`${col(5+i)}${r}`;
  if(formulas[i]) f(n,a,formulas[i],fmt); else {sheets[n].getRange(a).setNumberFormat(fmt);sheets[n].getRange(a).format.font.color=typeof arr[i]==='number'?blue:muted;}
  if(definition)note(n,a,`${label}. ${definition}${formulas[i]?'\nExcel formula: '+formulas[i]:''}`);
 }
 if(fmt.includes('%'))sheets[n].getRange(`C${r}:${col(4+arr.length)}${r}`).format.font.italic=true;
 note(n,`C${r}`,definition||label);
}
function scalar(n,r,label,x,fmt=amount,definition=''){row(n,r,label,[x],fmt,definition);}
function total(n,r,last='I'){const rr=sheets[n].getRange(`C${r}:${last}${r}`);rr.format.font.bold=true;rr.format.borders={top:{style:'thin',color:navy}};}
function section(n,r,title,last='K'){v(n,`C${r}`,title);sheets[n].getRange(`C${r}:${last}${r}`).format={fill:pale,font:{name:font,size:10,bold:true,color:ink},borders:{preset:'outside',style:'thin',color:'#CBD5E1'},rowHeight:24};}
