 const opts=x=>criterion==='revenue CAGR'?{growth:x}:criterion==='WACC'?{discount:x}:{tg:x};
 scalar(n,20,'Value at lower solver bound',`=${evExpression(opts('$E$16'))}`,amount);scalar(n,21,'Value at upper solver bound',`=${evExpression(opts('$E$17'))}`,amount);
 scalar(n,14,'Economically permitted?',business,'General',explanation);
 analysis(n,23,[explanation,'The selected fiscal operating margins, tax, D&A, capital spending and NWC ratios stay fixed unless this sheet explicitly varies them. The stable ROIC and equity bridge stay fixed.','The solver table is formula driven and recalculates after case or input changes. Bracket validity is checked before reporting a root. Mathematical solutions outside operating bounds are identified explicitly.']);
 headers(n,33,['Step','Lower bound','Upper bound','Midpoint','Enterprise value','Value residual'],3);
 for(let i=0;i<48;i++){const r=34+i,p=r-1;v(n,`C${r}`,i+1,'0');
  f(n,`D${r}`,i?`=IF(G${p}${increasing?'<':'>'}$E$9,F${p},D${p})`:'=$E$16',formatter);
  f(n,`E${r}`,i?`=IF(G${p}${increasing?'<':'>'}$E$9,E${p},F${p})`:'=$E$17',formatter);
  f(n,`F${r}`,`=(D${r}+E${r})/2`,formatter);f(n,`G${r}`,`=${evExpression(opts(`F${r}`))}`,amount);f(n,`H${r}`,`=G${r}-$E$9`,amount);
 }
