function casePriceExpression(k,g){
 const ar=(key,j)=>R('Assumptions',`${col(5+j)}${caseRows[key][k]}`);
 const revenue=j=>`SUM(${['pbp','ic','mpc'].map((seg,h)=>`${R('Historical Inputs',`$N$${histRow[seg+'_revenue']}`)}${Array.from({length:j+1},(_,t)=>`*(1+${ar(['pbp_growth','ic_growth','mpc_growth'][h],t)})`).join('')}`).join(',')})`;
 const flows=Array.from({length:5},(_,j)=>`((${revenue(j)})*(${ar('ebit_margin',j)}*(1-${ar('tax_rate',j)})+${ar('da_ratio',j)}-${ar('cash_capex_ratio',j)}+${ar('capitalized_interest_ratio',j)}-${ar('finance_lease_add_ratio',j)}-${ar('nwc_ratio',j)})+${j?`(${revenue(j-1)})*${ar('nwc_ratio',j-1)}`:R('Working Capital','$E$6')})*${R('DCF',`${col(5+j)}12`)}/${R('DCF',`${col(5+j)}14`)}`);
 const terminal=`(${revenue(4)})*(1+(${g}))*${R('Assumptions',`$E$${stableRows.terminal_margin+1+k}`)}*(1-${R('Assumptions','$E$15')})*(1-(${g})/${R('Assumptions',`$E$${stableRows.terminal_roic+1+k}`)})/(${R('DCF','$E$6')}-(${g}))/${R('DCF','$E$20')}`;
 return `(SUM(${flows.join(',')})+${terminal}+${R('Equity Bridge','$E$17')})/${R('Equity Bridge','$E$20')}`;
}
